export function scriptedModel(answer) {
    return Model.make({
        stream: (request) => Stream.suspend(() => {
            const ask = [
                ...request.system.map((part) => part.text),
                ...request.messages.flatMap((message) => message.content.flatMap((part) => (part.type === "text" ? [part.text] : []))),
